 28	    public async Task CreateOrderAsync(Models.Orders.Order newOrder)
 29	    {
 30	        var authToken = await _identityService.GetAuthTokenAsync().ConfigureAwait(false);
 31	
 32	        if (string.IsNullOrEmpty(authToken))
 33	        {
 34	            return;
 35	        }
 36	
 37	        var uri = $"{UriHelper.CombineUri(_settingsService.GatewayOrdersEndpointBase, ApiUrlBase)}?{ApiVersion}";
 38	
 39	        var success = await _requestProvider.PostAsync(uri, newOrder, authToken, "x-requestid").ConfigureAwait(false);
 40	    }
