 42	    public async Task<IEnumerable<Models.Orders.Order>> GetOrdersAsync()
 43	    {
 44	        var authToken = await _identityService.GetAuthTokenAsync().ConfigureAwait(false);
 45	
 46	        if (string.IsNullOrEmpty(authToken))
 47	        {
 48	            return Enumerable.Empty<Models.Orders.Order>();
 49	        }
 50	
 51	        var uri = $"{UriHelper.CombineUri(_settingsService.GatewayOrdersEndpointBase, ApiUrlBase)}?{ApiVersion}";
 52	
 53	        var orders =
 54	            await _requestProvider.GetAsync<IEnumerable<Models.Orders.Order>>(uri, authToken).ConfigureAwait(false);
 55	
 56	        return orders ?? Enumerable.Empty<Models.Orders.Order>();
 57	    }
