 60	    {
 61	        var authToken = await _identityService.GetAuthTokenAsync().ConfigureAwait(false);
 62	
 63	        if (string.IsNullOrEmpty(authToken))
 64	        {
 65	            return new Models.Orders.Order();
 66	        }
 67	
 68	        try
 69	        {
 70	            var uri = $"{UriHelper.CombineUri(_settingsService.GatewayOrdersEndpointBase, $"{ApiUrlBase}/{orderId}")}?{ApiVersion}";
 71	
 72	            var order =
 73	                await _requestProvider.GetAsync<Models.Orders.Order>(uri, authToken).ConfigureAwait(false);
 74	
 75	            return order;
 76	        }
 77	        catch
 78	        {
 79	            return new Models.Orders.Order();
 80	        }
 81	    }
