 83	    public async Task<bool> CancelOrderAsync(int orderId)
 84	    {
 85	        var authToken = await _identityService.GetAuthTokenAsync().ConfigureAwait(false);
 86	
 87	        if (string.IsNullOrEmpty(authToken))
 88	        {
 89	            return false;
 90	        }
 91	
 92	        var uri = $"{UriHelper.CombineUri(_settingsService.GatewayOrdersEndpointBase, $"{ApiUrlBase}/cancel")}?{ApiVersion}";
 93	
 94	        var cancelOrderCommand = new CancelOrderCommand(orderId);
 95	
 96	        var header = "x-requestid";
 97	
