111	    private Task NotifyChangeSubscribersAsync()
112	        => Task.WhenAll(_changeSubscriptions.Select(s => s.NotifyAsync()));
113	
114	    private async Task<ClaimsPrincipal> GetUserAsync()
115	        => (await authenticationStateProvider.GetAuthenticationStateAsync()).User;
116	
117	    private Task<IReadOnlyCollection<BasketItem>> FetchBasketItemsAsync()
118	    {
119	        return _cachedBasket ??= FetchCoreAsync();
120	
121	        async Task<IReadOnlyCollection<BasketItem>> FetchCoreAsync()
122	        {
123	            var quantities = await basketService.GetBasketAsync();
124	            if (quantities.Count == 0)
125	            {
126	                return [];
127	            }
128	
129	            // Get details for the items in the basket
130	            var basketItems = new List<BasketItem>();
131	            var productIds = quantities.Select(row => row.ProductId);
132	            var catalogItems = (await catalogService.GetCatalogItems(productIds)).ToDictionary(k => k.Id, v => v);
133	            foreach (var item in quantities)
134	            {
135	                var catalogItem = catalogItems[item.ProductId];
136	                var orderItem = new BasketItem
137	                {
138	                    Id = Guid.NewGuid().ToString(), // TODO: this value is meaningless, use ProductId instead.
139	                    ProductId = catalogItem.Id,
140	                    ProductName = catalogItem.Name,
141	                    UnitPrice = catalogItem.Price,
142	                    Quantity = item.Quantity,
143	                };
144	                basketItems.Add(orderItem);
145	            }
146	
147	            return basketItems;
148	        }
149	    }
