151	    private class BasketStateChangedSubscription(BasketState Owner, EventCallback Callback) : IDisposable
152	    {
153	        public Task NotifyAsync() => Callback.InvokeAsync();
154	        public void Dispose() => Owner._changeSubscriptions.Remove(this);
155	    }
156	}
