 4	                    : INotificationHandler<OrderStartedDomainEvent>
 5	{
 6	    private readonly ILogger _logger;
 7	    private readonly IBuyerRepository _buyerRepository;
 8	    private readonly IOrderingIntegrationEventService _orderingIntegrationEventService;
 9	
10	    public ValidateOrAddBuyerAggregateWhenOrderStartedDomainEventHandler(
11	        ILogger<ValidateOrAddBuyerAggregateWhenOrderStartedDomainEventHandler> logger,
12	        IBuyerRepository buyerRepository,
13	        IOrderingIntegrationEventService orderingIntegrationEventService)
14	    {
15	        _buyerRepository = buyerRepository ?? throw new ArgumentNullException(nameof(buyerRepository));
16	        _orderingIntegrationEventService = orderingIntegrationEventService ?? throw new ArgumentNullException(nameof(orderingIntegrationEventService));
17	        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
18	    }
