20	    public async Task Handle(OrderStartedDomainEvent domainEvent, CancellationToken cancellationToken)
21	    {
22	        var cardTypeId = domainEvent.CardTypeId != 0 ? domainEvent.CardTypeId : 1;
23	        var buyer = await _buyerRepository.FindAsync(domainEvent.UserId);
24	        var buyerExisted = buyer is not null;
25	
26	        if (!buyerExisted)
27	        {
28	            buyer = new Buyer(domainEvent.UserId, domainEvent.UserName);
29	        }
30	
31	        // REVIEW: The event this creates needs to be sent after SaveChanges has propagated the buyer Id. It currently only
32	        // works by coincidence. If we remove HiLo or if anything decides to yield earlier, it will break.
33	
34	        buyer.VerifyOrAddPaymentMethod(cardTypeId,
35	                                        $"Payment Method on {DateTime.UtcNow}",
36	                                        domainEvent.CardNumber,
37	                                        domainEvent.CardSecurityNumber,
38	                                        domainEvent.CardHolderName,
39	                                        domainEvent.CardExpiration,
40	                                        domainEvent.Order.Id);
41	
42	        if (!buyerExisted)
43	        {
44	            _buyerRepository.Add(buyer);
45	        }
46	
47	        await _buyerRepository.UnitOfWork
48	            .SaveEntitiesAsync(cancellationToken);
49	
50	        var integrationEvent = new OrderStatusChangedToSubmittedIntegrationEvent(domainEvent.Order.Id, domainEvent.Order.OrderStatus, buyer.Name, buyer.IdentityGuid);
51	        await _orderingIntegrationEventService.AddAndSaveEventAsync(integrationEvent);
52	        OrderingApiTrace.LogOrderBuyerAndPaymentValidatedOrUpdated(_logger, buyer.Id, domainEvent.Order.Id);
53	    }
54	}
