10	    public IntegrationEventLogService(TContext context)
11	    {
12	        _context = context;
13	        _eventTypes = Assembly.Load(Assembly.GetEntryAssembly().FullName)
14	            .GetTypes()
15	            .Where(t => t.Name.EndsWith(nameof(IntegrationEvent)))
16	            .ToArray();
17	    }
