10	    public static IEventBusBuilder ConfigureJsonOptions(this IEventBusBuilder eventBusBuilder, Action<JsonSerializerOptions> configure)
11	    {
12	        eventBusBuilder.Services.Configure<EventBusSubscriptionInfo>(o =>
13	        {
14	            configure(o.JsonSerializerOptions);
15	        });
16	
17	        return eventBusBuilder;
18	    }
19	
20	    public static IEventBusBuilder AddSubscription<T, [DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicConstructors)] TH>(this IEventBusBuilder eventBusBuilder)
21	        where T : IntegrationEvent
22	        where TH : class, IIntegrationEventHandler<T>
23	    {
24	        // Use keyed services to register multiple handlers for the same event type
25	        // the consumer can use IKeyedServiceProvider.GetKeyedService<IIntegrationEventHandler>(typeof(T)) to get all
26	        // handlers for the event type.
27	        eventBusBuilder.Services.AddKeyedTransient<IIntegrationEventHandler, TH>(typeof(T));
28	
29	        eventBusBuilder.Services.Configure<EventBusSubscriptionInfo>(o =>
30	        {
31	            // Keep track of all registered event types and their name mapping. We send these event types over the message bus
32	            // and we don't want to do Type.GetType, so we keep track of the name mapping here.
33	
34	            // This list will also be used to subscribe to events from the underlying message broker implementation.
35	            o.EventTypes[typeof(T).Name] = typeof(T);
36	        });
37	
38	        return eventBusBuilder;
39	    }
40	}
