 1	﻿using Microsoft.AspNetCore.Http.HttpResults;
 2	using Microsoft.AspNetCore.Mvc;
 3	
 4	namespace eShop.WebhookClient.Endpoints;
 5	
 6	public static class WebhookEndpoints
 7	{
 8	    public static IEndpointRouteBuilder MapWebhookEndpoints(this IEndpointRouteBuilder app)
 9	    {
10	        const string webhookCheckHeader = "X-eshop-whtoken";
11	
12	        var configuration = app.ServiceProvider.GetRequiredService<IConfiguration>();
13	        bool.TryParse(configuration["ValidateToken"], out var validateToken);
14	        var tokenToValidate = configuration["WebhookClientOptions:Token"];
15	
16	        app.MapMethods("/check", [HttpMethods.Options], Results<Ok, BadRequest<string>> ([FromHeader(Name = webhookCheckHeader)] string value, HttpResponse response) =>
17	        {
18	            if (!validateToken || value == tokenToValidate)
19	            {
20	                if (!string.IsNullOrWhiteSpace(value))
21	                {
22	                    response.Headers.Append(webhookCheckHeader, value);
23	                }
24	
25	                return TypedResults.Ok();
26	            }
27	
28	            return TypedResults.BadRequest("Invalid token");
29	        });
30	
31	        app.MapPost("/webhook-received", async (WebhookData hook, HttpRequest request, ILogger<Program> logger, HooksRepository hooksRepository) =>
32	        {
33	            var token = request.Headers[webhookCheckHeader];
34	
35	            logger.LogInformation("Received hook with token {Token}. My token is {MyToken}. Token validation is set to {ValidateToken}", token, tokenToValidate, validateToken);
36	
37	            if (!validateToken || tokenToValidate == token)
38	            {
39	                logger.LogInformation("Received hook is going to be processed");
40	                var newHook = new WebHookReceived()
41	                {
42	                    Data = hook.Payload,
43	                    When = hook.When,
44	                    Token = token
45	                };
46	                await hooksRepository.AddNew(newHook);
47	                logger.LogInformation("Received hook was processed.");
48	                return Results.Ok(newHook);
49	            }
50	
51	            logger.LogInformation("Received hook is NOT processed - Bad Request returned.");
52	            return Results.BadRequest();
53	        });
54	
55	        return app;
56	    }
57	}
