 2	
 3	namespace eShop.WebhookClient.Services;
 4	
 5	public class HooksRepository
 6	{
 7	    private readonly ConcurrentQueue<WebHookReceived> _data = new();
 8	    private readonly ConcurrentDictionary<OnChangeSubscription, object?> _onChangeSubscriptions = new();
 9	
10	    public Task AddNew(WebHookReceived hook)
11	    {
12	        _data.Enqueue(hook);
13	
14	        foreach (var subscription in _onChangeSubscriptions)
15	        {
16	            try
17	            {
18	                _ = subscription.Key.NotifyAsync();
19	            }
20	            catch (Exception)
21	            {
22	                // It's the subscriber's responsibility to report/handle any exceptions
23	                // that occur during their callback
24	            }
25	        }
26	
27	        return Task.CompletedTask;
28	    }
29	
30	    public Task<IEnumerable<WebHookReceived>> GetAll()
31	    {
32	        return Task.FromResult(_data.AsEnumerable());
33	    }
34	
35	    public IDisposable Subscribe(Func<Task> callback)
36	    {
37	        var subscription = new OnChangeSubscription(callback, this);
38	        _onChangeSubscriptions.TryAdd(subscription, null);
39	        return subscription;
40	    }
41	
