 2	public class LoggingBehavior<TRequest, TResponse> : IPipelineBehavior<TRequest, TResponse> where TRequest : IRequest<TResponse>
 3	{
 4	    private readonly ILogger<LoggingBehavior<TRequest, TResponse>> _logger;
 5	    public LoggingBehavior(ILogger<LoggingBehavior<TRequest, TResponse>> logger) => _logger = logger;
 6	
 7	    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken cancellationToken)
 8	    {
 9	        _logger.LogInformation("Handling command {CommandName} ({@Command})", request.GetGenericTypeName(), request);
