     6	    {
     7	        var domainEntities = ctx.ChangeTracker
     8	            .Entries<Entity>()
     9	            .Where(x => x.Entity.DomainEvents != null && x.Entity.DomainEvents.Any());
    10	
    11	        var domainEvents = domainEntities
    12	            .SelectMany(x => x.Entity.DomainEvents)
    13	            .ToList();
    14	
    15	        domainEntities.ToList()
    16	            .ForEach(entity => entity.Entity.ClearDomainEvents());
    17	
    18	        foreach (var domainEvent in domainEvents)
    19	            await mediator.Publish(domainEvent);
    20	    }
    21	}
